```javascript
import axios from 'axios';
import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const SERVICE_URL = 'https://ваш-веб-сайт.com'; // Замените на ваш основной URL
const MAINTENANCE_PAGE_URL = 'https://ваш-сайт-техническое-обслуживание.com'; // URL страницы технического обслуживания

const ServiceWorker = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const checkWebsiteAvailability = async () => {
      try {
        const response = await axios.get(SERVICE_URL, { timeout: 5000 }); // Попытка загрузки сайта за 5 секунд
        navigate('/'); // Перенаправление на главную страницу, если сайт доступен
      } catch (error) {
        if (error.response && error.response.status === 503) {
          navigate(MAINTENANCE_PAGE_URL); // Перенаправление на страницу технического обслуживания при 503 ошибке
        }
      }
    };

    checkWebsiteAvailability();
  }, [navigate]);

  return null;
};

export default ServiceWorker;
```

